 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    q = (y+dy, x+dx)
                    if 0 <= q[0] < h and 0 <= q[1] < w and q not in seen and grid[q[0]][q[1]] == color:
                        seen.add(q)
                        stack.append(q)
            objects.append((color, cells))
    # Process the objects nearest the right edge first; each slides right until blocked.
    objects.sort(key=lambda obj: max(c for _, c in obj[1]), reverse=True)
    out = [[0]*w for _ in range(h)]
    for color, cells in objects:
        shift = 0
        while True:
            nshift = shift + 1
            if any(c+nshift >= w or out[r][c+nshift] != 0 for r, c in cells):
                break
            shift = nshift
        for r, c in cells:
            out[r][c+shift] = color
    return out
